while True:
    try:
        N = int(input("Enter a number: "))
        break
    except ValueError:
        print("Invalid input. Please enter a number.")

for i in range(1, N+1):
    if i % 3 == 0 and i % 5 == 0:
        print("FizzBuzz")
    elif i % 3 == 0:
        print("Fizz")
    elif i % 5 == 0:
        print("Buzz")
    else:
        print(i)
``` 
